// PEGAR DADOS COMPLETOS DO WEBHOOK E PROCESSAR
const webhookData = $('Webhook').first().json.body.data;

const charts = webhookData.map((file, index) => {
  const content = file.content;
  const name = content.name || file.filename;
  const description = content.description || '';

  let data = [];
  let chartType = 'bar';

  // Extrair dados baseado na estrutura
  if (content.data) {
    const firstKey = Object.keys(content.data)[0];
    const allData = content.data[firstKey];

    if (Array.isArray(allData) && allData.length > 0) {
      // Dados com columns (tabelas)
      if (allData[0].columns) {
        // Para tabelas de métricas (installs, uninstalls, etc)
        if (allData[0].columns.find(c => c.field === 'installs' || c.field === 'uninstalls')) {
          data = allData[0].columns
            .filter(col => col.value !== null && col.value !== undefined)
            .map(col => ({
              name: col.field === 'installs' ? 'Instalações' :
                    col.field === 'uninstalls' ? 'Desinstalações' :
                    col.field === 'dau' ? 'DAU' :
                    col.field === 'account_opening' ? 'Abertura de Contas' : col.field,
              value: Number(col.value)
            }));
          chartType = 'pie';
        }
        // Para tabelas de keywords/items
        else {
          data = allData.slice(0, 20).map(row => ({
            name: row.columns.find(c => c.field === 'keyword' || c.field === 'title')?.value || 'Item',
            value: Number(row.columns.find(c => c.field === 'position' || c.field === 'total')?.value || 0)
          }));
          chartType = 'bar';
        }
      }
      // Dados simples (gráficos temporais)
      else {
        const xField = content.xField || 'createdAt';
        const yField = content.yField || 'value';
        data = allData.slice(0, 50).map(i => ({
          name: String(i[xField] || '').substring(0, 10),
          value: Number(i[yField] || i.value || i.total || 0)
        }));
        chartType = content.kind === 'area' || content.kind === 'line' ? 'line' : 'bar';
      }
    }
  }

  return {
    title: name,
    description: description.substring(0, 150),
    type: chartType,
    data: data.filter(d => d.value && !isNaN(d.value))
  };
});

return { charts: charts.filter(c => c.data.length > 0) };

// Pegar charts do Build Dashboard (node anterior à IA)
const buildOutput = $('Build Dashboard').first().json;
const charts = buildOutput.charts || [];

// Pegar análise da IA
const aiAnalysis = $json.output;

let analysis = {};
if (typeof aiAnalysis === 'string') {
  const match = aiAnalysis.match(/\{[\s\S]*\}/);
  if (match) {
    try { analysis = JSON.parse(match[0]); } catch(e) {}
  }
} else {
  analysis = aiAnalysis;
}

return {
  charts: charts,
  analysis: analysis
};
